-- Consolidate catalog read policies while keeping administrator writes separate.
drop policy public_read on public.occasions;
drop policy admin_manage on public.occasions;
create policy catalog_read on public.occasions for select to anon, authenticated using (is_active or (select private.is_admin()));
create policy admin_insert on public.occasions for insert to authenticated with check ((select private.is_admin()));
create policy admin_update on public.occasions for update to authenticated using ((select private.is_admin())) with check ((select private.is_admin()));
create policy admin_delete on public.occasions for delete to authenticated using ((select private.is_admin()));
